window.LT_FAQ = [{"q":"How do I hear a letter?","a":"Open Letters (எழுத்துகள்) and tap any letter tile. The big letter, its sound and a picture word appear at the top; press 🔊 to hear it again. Vowels play the letter and then their picture word.","tags":"sound hear listen play letter tap audio","link":"./#/uyir","lang":"en","help":1},{"q":"The sound is wrong or there is no sound","a":"Sounds come from your device's Tamil text-to-speech voice, which can mispronounce single letters. To get a Tamil voice — Android: Settings → Text-to-speech → Google → install Tamil. Windows: Settings → Time & language → Speech → add Tamil. iPhone/Mac: Settings → Accessibility → Spoken Content → Voices → Tamil. Microsoft Edge has clearer Tamil voices. If you hear a mistake, please [report it on GitHub Issues](https://github.com/jssuthahar/learntamil/issues).","tags":"sound voice wrong no not working mute silent pronounce pronunciation audio speaker tts","link":"","lang":"en","help":1},{"q":"How do I install Learn Tamil as an app?","a":"On Android, Chrome or Edge, tap the ⬇ Install app button at the top. On iPhone or iPad, open the site in Safari, tap Share and then Add to Home Screen. The app opens full screen and has shortcuts to Letters, Reading, Stories, Games and Certificate.","tags":"install app download home screen phone mobile iphone android pwa","link":"","lang":"en","help":1},{"q":"Does it work offline?","a":"Yes. After your first visit, letters, reading, stories, games, certificates and the guide pages work without internet. Sounds from the device voice work offline only if the voice is stored on the device.","tags":"offline internet wifi network connection data","link":"","lang":"en","help":1},{"q":"How do I get a certificate?","a":"Open 🎓 Certificate, choose one of the 10 levels and answer the questions (10 questions, pass with 8; the Champion level has 15, pass with 12). Type the name and download the certificate as a PDF. Each level unlocks the next, and every test asks new questions. Certificates are for encouragement, not an official qualification.","tags":"certificate cert pdf level test exam pass download சான்றிதழ்","link":"./#/certificate","lang":"en","help":1},{"q":"What are tokens and badges?","a":"Children earn 🪙 tokens for right answers, finished games, words read, stories and certificates, and unlock 🏅 badges such as “முதல் அடி” (first step). Tap 🪙 at the top to see them. They are saved only on this device.","tags":"token tokens coin coins badge badges reward rewards star stars points score","link":"","lang":"en","help":1},{"q":"How do I reset progress?","a":"Tap 🪙 at the top to open My rewards, then press Reset progress. You can also clear this site’s data in your browser settings.","tags":"reset clear delete progress start again restart","link":"","lang":"en","help":1},{"q":"Which games are there?","a":"Six games: க் + ஆ = ? (build a letter), Listen & pick, Spin wheel, Balloon pop, Word builder and Memory. Every right answer gives points, a cheer and tokens; 3 in a row gives a bonus.","tags":"game games play fun quiz balloon spin memory word builder","link":"./#/practice","lang":"en","help":1},{"q":"Is my child’s data safe?","a":"Yes. Learn Tamil collects no personal data: no accounts, no cookies, no analytics, no ads and no tracking. Progress and the certificate name are saved only in your own browser. See the [Privacy & data policy](privacy.html).","tags":"privacy data safe tracking personal cookies child children secure gdpr coppa","link":"privacy.html","lang":"en","help":1},{"q":"How can I report a mistake or give feedback?","a":"Please open an issue on [GitHub Issues](https://github.com/jssuthahar/learntamil/issues). There are short forms for a wrong sound or Tamil mistake, a bug, or an idea. Issues are public, so please don’t include personal details.","tags":"report mistake bug error wrong issue feedback idea suggest problem github","link":"","lang":"en","help":1},{"q":"How can I support Learn Tamil?","a":"Learn Tamil is free with no ads. If it helps your family or classroom, you can [buy me a coffee](https://buymeacoffee.com/jssuthahar) ☕. Thank you — உங்கள் ஆதரவுக்கு நன்றி!","tags":"support donate coffee pay money help contribute sponsor","link":"","lang":"en","help":1},{"q":"Who made Learn Tamil?","a":"Learn Tamil was made by Suthahar Jegatheesan (MSDEVBUILD) as a free, non-commercial project for children and beginners learning Tamil. More at [blog.msdevbuild.com](https://blog.msdevbuild.com).","tags":"who made author creator owner msdevbuild suthahar about contact","link":"","lang":"en","help":1},{"q":"Where can I read Tamil stories?","a":"Open Stories (கதைகள்) in the app to hear five short stories read aloud — tap any word to see its letters. You can also read them as text with English meaning on the [Tamil stories page](tamil-stories-for-kids.html).","tags":"story stories read kathai கதை moral","link":"./#/stories","lang":"en","help":1},{"q":"Where can I download printable worksheets and charts?","a":"Free printable PDFs — Tamil alphabet charts, an uyirmei chart, a numbers chart and letter tracing worksheets — are on the [printables page](tamil-printables.html). Print them on A4 or Letter paper.","tags":"printable print worksheet worksheets pdf chart tracing trace download sheet paper","link":"tamil-printables.html","lang":"en","help":1},{"q":"What word topics can my child learn?","a":"In Reading (வாசிப்பு) choose a topic: numbers 1–10, colours, days of the week, parts of the body, family and fruits & food. Each word shows its picture and letters and can be heard aloud.","tags":"topic topics numbers colours colors days week body family fruit fruits food vocabulary words","link":"./#/reading","lang":"en","help":1},{"q":"How does reading practice work?","a":"Open Reading (வாசிப்பு). Read the word yourself, tap 🐢 to hear it letter by letter, then show the picture to check. There are three levels: 2, 3 and 4+ letter words.","tags":"reading read practice words level spell","link":"./#/reading","lang":"en","help":1},{"q":"Why are Tamil vowels called uyir (life)?","a":"In Tamil grammar the vowels are called உயிர் (uyir, “life”) and the consonants மெய் (mei, “body”). When a consonant joins a vowel it becomes உயிர்மெய் (uyirmei, “life + body”), like a body that comes alive.","tags":"","link":"tamil-vowels.html","lang":"en"},{"q":"What is the difference between kuril and nedil?","a":"குறில் (kuril) vowels are short and are held for about one beat (one மாத்திரை, maathirai). நெடில் (nedil) vowels are long and are held for about two beats. The short vowels are அ இ உ எ ஒ and the long vowels are ஆ ஈ ஊ ஏ ஐ ஓ ஔ.","tags":"","link":"tamil-vowels.html","lang":"en"},{"q":"What are mudhal ezhuthukal (primary letters)?","a":"The 12 vowels and 18 consonants together — 30 letters — are called முதல் எழுத்துகள் (mudhal ezhuthukal, primary letters). Uyirmei letters and ஃ belong to the சார்பு எழுத்துகள் (saarbu ezhuthukal, dependent letters).","tags":"","link":"tamil-vowels.html","lang":"en"},{"q":"How are Tamil vowels written after a consonant?","a":"After a consonant, each vowel (except அ) is written as a vowel sign: ா for ஆ, ி for இ, ீ for ஈ, ு for உ, ூ for ஊ, ெ for எ, ே for ஏ, ை for ஐ, ொ for ஒ, ோ for ஓ and ௌ for ஔ. For example க் + ஆ = கா and க் + ஐ = கை. With அ the consonant simply loses its dot: க் + அ = க.","tags":"","link":"tamil-vowels.html","lang":"en"},{"q":"Why do Tamil consonants have a dot on top?","a":"The dot is called புள்ளி (pulli). It shows a pure consonant with no vowel sound, for example க் (k). When a vowel is added the dot goes away: க் + அ = க (ka).","tags":"","link":"tamil-consonants.html","lang":"en"},{"q":"What is the difference between ந, ன and ண?","a":"All three are “n” sounds. ந is said with the tongue at the teeth and mostly starts words (நாய்) or comes before த (பந்து). ன is said with the tongue at the gum and comes in the middle or end of words (மீன்). ண is said with the tongue curled back (கண்).","tags":"","link":"tamil-consonants.html","lang":"en"},{"q":"What do vallinam, mellinam and idaiyinam mean?","a":"They are the three groups of Tamil consonants. வல்லினம் (vallinam) are hard sounds: க் ச் ட் த் ப் ற். மெல்லினம் (mellinam) are soft, nasal sounds: ங் ஞ் ண் ந் ம் ன். இடையினம் (idaiyinam) are in-between sounds: ய் ர் ல் வ் ழ் ள்.","tags":"","link":"tamil-consonants.html","lang":"en"},{"q":"How do you say a Tamil consonant on its own?","a":"In school a pure consonant is usually read with a short இ before it, so க் is said “ik” and ங் is said “ing”. This makes the consonant sound easy to hear.","tags":"","link":"tamil-consonants.html","lang":"en"},{"q":"How do you read the uyirmei chart?","a":"Each row is a consonant and each column is a vowel. Find the consonant on the left and the vowel at the top; the letter where they meet is the uyirmei letter. For example, row ம் and column ஆ give மா.","tags":"","link":"uyirmei-ezhuthukal.html","lang":"en"},{"q":"How many uyirmei letters are short and how many are long?","a":"An uyirmei letter is short or long depending on its vowel. With the 5 short vowels there are 18 × 5 = 90 short (குறில்) uyirmei letters, and with the 7 long vowels there are 18 × 7 = 126 long (நெடில்) uyirmei letters. 90 + 126 = 216.","tags":"","link":"uyirmei-ezhuthukal.html","lang":"en"},{"q":"What is க வரிசை (the ka row)?","a":"க வரிசை is the row of 12 letters made from க்: க கா கி கீ கு கூ கெ கே கை கொ கோ கௌ. Children usually learn uyirmei one row at a time, starting with this row.","tags":"","link":"uyirmei-ezhuthukal.html","lang":"en"},{"q":"Which uyirmei letters are hardest to write?","a":"The உ and ஊ forms (like கு, சு, டு, து, பு and கூ, சூ, டூ) change shape for each consonant, so they are best learned row by row. The ொ, ோ and ௌ forms are written on both sides of the consonant, as in கொ, கோ and கௌ.","tags":"","link":"uyirmei-ezhuthukal.html","lang":"en"},{"q":"What are the first Tamil words a child should learn?","a":"Short two-letter words with clear pictures are best to start: ஆடு (goat), மீன் (fish), பூனை (cat), நாய் (dog), இலை (leaf), வீடு (house) and நிலா (moon). Then move on to three-letter words like மரம் (tree) and பந்து (ball).","tags":"","link":"tamil-words-for-kids.html","lang":"en"},{"q":"What are the names of animals in Tamil?","a":"Some animal names in Tamil: ஆடு (goat), மான் (deer), மீன் (fish), பூனை (cat), நாய் (dog), எலி (rat), பசு (cow), யானை (elephant), கிளி (parrot), ஆமை (tortoise), கோழி (hen), பாம்பு (snake), முயல் (rabbit), தவளை (frog), குதிரை (horse), கரடி (bear), மயில் (peacock), வாத்து (duck), சிங்கம் (lion), குரங்கு (monkey), ஒட்டகம் (camel).","tags":"","link":"tamil-words-for-kids.html","lang":"en"},{"q":"How can I help my child read Tamil words?","a":"Point to each letter and say its sound, then blend the sounds together: ஆ + டு = ஆடு. Start with two-letter words, use pictures, and practise a few words every day. The Reading section of the Learn Tamil app does this letter by letter with sound.","tags":"","link":"tamil-words-for-kids.html","lang":"en"},{"q":"Which Tamil stories are good for young children?","a":"Short stories with animals and a clear lesson work well: என் காலை (My Morning), காகமும் பானையும் (The Thirsty Crow), சிங்கமும் எலியும் (The Lion and the Mouse), முயலும் ஆமையும் (The Hare and the Tortoise), பாட்டியின் மாம்பழம் (Grandma’s Mango). Each is told in a few simple sentences.","tags":"","link":"tamil-stories-for-kids.html","lang":"en"},{"q":"What is the moral of காகமும் பானையும் (The Thirsty Crow)?","a":"The moral of காகமும் பானையும் (The Thirsty Crow) is “முயற்சி செய்தால் வெற்றி கிடைக்கும்.” — If you keep trying, you will succeed.","tags":"","link":"tamil-stories-for-kids.html","lang":"en"},{"q":"What is the moral of சிங்கமும் எலியும் (The Lion and the Mouse)?","a":"The moral of சிங்கமும் எலியும் (The Lion and the Mouse) is “சிறியவர்களும் பெரிய உதவி செய்ய முடியும்.” — Even the small can give big help.","tags":"","link":"tamil-stories-for-kids.html","lang":"en"},{"q":"What is the moral of முயலும் ஆமையும் (The Hare and the Tortoise)?","a":"The moral of முயலும் ஆமையும் (The Hare and the Tortoise) is “நிதானமாகத் தொடர்ந்து செய்தால் வெற்றி நிச்சயம்.” — Slow and steady wins the race.","tags":"","link":"tamil-stories-for-kids.html","lang":"en"},{"q":"How many letters are there in the Tamil alphabet?","a":"There are 247 letters in the Tamil alphabet: 12 vowels (உயிர் எழுத்துகள், uyir ezhuthukal), 18 consonants (மெய் எழுத்துகள், mei ezhuthukal), 1 special letter ஃ (ஆய்த எழுத்து, aaytha ezhuthu) and 216 consonant-vowel letters (உயிர்மெய் எழுத்துகள், uyirmei ezhuthukal). 12 + 18 + 1 + 216 = 247.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"What are the 12 Tamil vowels (uyir ezhuthukal)?","a":"The 12 Tamil vowels are அ ஆ இ ஈ உ ஊ எ ஏ ஐ ஒ ஓ ஔ. Five are short (குறில், kuril): அ இ உ எ ஒ. Seven are long (நெடில், nedil): ஆ ஈ ஊ ஏ ஐ ஓ ஔ.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"What are the 18 Tamil consonants (mei ezhuthukal)?","a":"The 18 Tamil consonants are க் ங் ச் ஞ் ட் ண் த் ந் ப் ம் ய் ர் ல் வ் ழ் ள் ற் ன். Each is written with a dot on top called புள்ளி (pulli). They form three groups of six: வல்லினம் (vallinam, hard) க் ச் ட் த் ப் ற்; மெல்லினம் (mellinam, soft) ங் ஞ் ண் ந் ம் ன்; இடையினம் (idaiyinam, medium) ய் ர் ல் வ் ழ் ள்.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"What are uyirmei letters and why are there 216?","a":"An uyirmei (உயிர்மெய்) letter is a consonant joined with a vowel, for example க் + அ = க, க் + ஆ = கா, க் + இ = கி. Each of the 18 consonants combines with each of the 12 vowels, so 18 × 12 = 216 uyirmei letters.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"What is the Tamil letter ஃ (aaytham)?","a":"ஃ is the ஆய்த எழுத்து (aaytha ezhuthu), also called அஃகேனம் or முப்புள்ளி (three dots). It is a single special letter that comes between a short vowel and a வல்லினம் letter, as in எஃகு (steel) and அஃது (that).","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"How do you pronounce ழ (zha) in Tamil?","a":"ழ (romanised \"zh\") is made by curling the tip of the tongue far back and letting the sound flow, somewhere between an \"r\" and an \"l\". It is heard in the word தமிழ் (Tamil). It is different from ல (l, as in \"love\") and ள (ḷ, l with the tongue curled back).","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"Are ஜ, ஷ, ஸ, ஹ part of the 247 Tamil letters?","a":"No. ஜ, ஷ, ஸ, ஹ, க்ஷ and ஸ்ரீ are Grantha letters used for words borrowed from other languages. They are widely used but are not counted in the 247 letters of the Tamil alphabet.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"What is the best way for a child to start learning Tamil letters?","a":"Start with the 12 uyir (vowel) letters and their sounds, then learn the 18 mei (consonant) letters. Next, learn uyirmei letters one consonant row at a time (க கா கி கீ …), then read simple two-letter words such as ஆடு (goat) and மீன் (fish). Short daily practice with sound and pictures works best.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"Is Learn Tamil free to use?","a":"Yes. Learn Tamil is completely free, needs no sign-up, shows no ads and does not track users. It works in any modern browser on phones, tablets and computers.","tags":"","link":"tamil-alphabet.html","lang":"en"},{"q":"தமிழில் எத்தனை எழுத்துகள் உள்ளன?","a":"தமிழில் மொத்தம் 247 எழுத்துகள் உள்ளன: 12 உயிர் எழுத்துகள், 18 மெய் எழுத்துகள், 1 ஆய்த எழுத்து, 216 உயிர்மெய் எழுத்துகள்.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"உயிர் எழுத்துகள் யாவை?","a":"அ ஆ இ ஈ உ ஊ எ ஏ ஐ ஒ ஓ ஔ ஆகிய 12 எழுத்துகள் உயிர் எழுத்துகள். இவற்றில் அ, இ, உ, எ, ஒ ஆகிய ஐந்தும் குறில்; ஆ, ஈ, ஊ, ஏ, ஐ, ஓ, ஔ ஆகிய ஏழும் நெடில்.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"மெய் எழுத்துகள் யாவை?","a":"க் ங் ச் ஞ் ட் ண் த் ந் ப் ம் ய் ர் ல் வ் ழ் ள் ற் ன் ஆகிய 18 எழுத்துகள் மெய் எழுத்துகள். இவை வல்லினம் (க் ச் ட் த் ப் ற்), மெல்லினம் (ங் ஞ் ண் ந் ம் ன்), இடையினம் (ய் ர் ல் வ் ழ் ள்) என மூன்று வகைப்படும்.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"உயிர்மெய் எழுத்துகள் எப்படி உருவாகின்றன?","a":"மெய் எழுத்துடன் உயிர் எழுத்து சேர்ந்து உயிர்மெய் எழுத்து உருவாகிறது. எடுத்துக்காட்டு: க் + அ = க, க் + ஆ = கா. 18 மெய் × 12 உயிர் = 216 உயிர்மெய் எழுத்துகள்.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"ஆய்த எழுத்து என்றால் என்ன?","a":"ஃ என்பது ஆய்த எழுத்து. இதை அஃகேனம், முப்புள்ளி என்றும் அழைப்பர். எடுத்துக்காட்டு: எஃகு, அஃது.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"முதல் எழுத்துகள் எவை?","a":"உயிர் எழுத்துகள் 12, மெய் எழுத்துகள் 18 — ஆக 30 எழுத்துகளும் முதல் எழுத்துகள் எனப்படும். உயிர்மெய், ஆய்தம் ஆகியவை சார்பு எழுத்துகள் வகையைச் சேர்ந்தவை.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"ஜ, ஷ, ஸ, ஹ தமிழ் எழுத்துகளா?","a":"ஜ, ஷ, ஸ, ஹ, க்ஷ, ஸ்ரீ ஆகியவை கிரந்த எழுத்துகள். பிறமொழிச் சொற்களை எழுத இவை பயன்படுகின்றன; 247 தமிழ் எழுத்துகளில் இவை சேர்க்கப்படுவதில்லை.","tags":"","link":"ezhuthukal.html","lang":"ta"},{"q":"How do you count from 1 to 10 in Tamil?","a":"1 ஒன்று (onru), 2 இரண்டு (irandu), 3 மூன்று (moonru), 4 நான்கு (naangu), 5 ஐந்து (ainthu), 6 ஆறு (aaru), 7 ஏழு (ezhu), 8 எட்டு (ettu), 9 ஒன்பது (onbathu), 10 பத்து (pathu).","tags":"","link":"tamil-numbers.html","lang":"en"},{"q":"How are numbers written in Tamil script?","a":"Tamil has its own numerals: ௧ (1), ௨ (2), ௩ (3), ௪ (4), ௫ (5), ௬ (6), ௭ (7), ௮ (8), ௯ (9) and ௰ (10). Today the digits 1, 2, 3 … are used in everyday writing; Tamil numerals are seen in older texts, calendars and formal uses.","tags":"","link":"tamil-numbers.html","lang":"en"},{"q":"What are the colours called in Tamil?","a":"Colours in Tamil: சிவப்பு (red), நீலம் (blue), பச்சை (green), மஞ்சள் (yellow), ஆரஞ்சு (orange), ஊதா (purple), பழுப்பு (brown), வெள்ளை (white), கறுப்பு (black), இளஞ்சிவப்பு (pink). The word for colour is நிறம் (niram); colours are நிறங்கள்.","tags":"","link":"tamil-colours.html","lang":"en"},{"q":"What is red in Tamil?","a":"Red in Tamil is சிவப்பு (sivappu). Blue is நீலம் (neelam), green is பச்சை (pachai) and yellow is மஞ்சள் (manjal).","tags":"","link":"tamil-colours.html","lang":"en"},{"q":"What are the days of the week in Tamil?","a":"The days of the week in Tamil are ஞாயிறு (Sunday), திங்கள் (Monday), செவ்வாய் (Tuesday), புதன் (Wednesday), வியாழன் (Thursday), வெள்ளி (Friday), சனி (Saturday). Each is often said with கிழமை, for example திங்கள்கிழமை (Monday).","tags":"","link":"tamil-days-of-the-week.html","lang":"en"},{"q":"Why are Tamil day names linked to the sun, moon and planets?","a":"Each Tamil day is named after a heavenly body: ஞாயிறு (the Sun) for Sunday, திங்கள் (the Moon) for Monday, செவ்வாய் (Mars) for Tuesday, புதன் (Mercury) for Wednesday, வியாழன் (Jupiter) for Thursday, வெள்ளி (Venus) for Friday and சனி (Saturn) for Saturday.","tags":"","link":"tamil-days-of-the-week.html","lang":"en"},{"q":"What are the parts of the body called in Tamil?","a":"Parts of the body in Tamil: தலை (head), கண் (eye), காது (ear), மூக்கு (nose), வாய் (mouth), பல் (tooth), முடி (hair), கை (hand), விரல் (finger), கால் (leg). The body is உடல் (udal) and its parts are உறுப்புகள் (uruppugal).","tags":"","link":"tamil-body-parts.html","lang":"en"},{"q":"How can children learn body parts in Tamil?","a":"Play a pointing game: say a word such as கண் (eye) or மூக்கு (nose) and let the child point to it. Then swap — the child says the word while you point.","tags":"","link":"tamil-body-parts.html","lang":"en"},{"q":"How do you say family members in Tamil?","a":"Family words in Tamil: அம்மா (mother), அப்பா (father), அண்ணன் (elder brother), அக்கா (elder sister), தம்பி (younger brother), தங்கை (younger sister), தாத்தா (grandfather), பாட்டி (grandmother). Family is குடும்பம் (kudumbam).","tags":"","link":"tamil-family-words.html","lang":"en"},{"q":"What is the difference between அண்ணன் and தம்பி?","a":"அண்ணன் (annan) is an elder brother and தம்பி (thambi) is a younger brother. In the same way, அக்கா (akka) is an elder sister and தங்கை (thangai) is a younger sister.","tags":"","link":"tamil-family-words.html","lang":"en"},{"q":"What are fruit names in Tamil?","a":"Fruit names in Tamil: மாம்பழம் (mango), வாழைப்பழம் (banana), திராட்சை (grapes), ஆப்பிள் (apple), தர்பூசணி (watermelon), அன்னாசி (pineapple), எலுமிச்சை (lemon), தேங்காய் (coconut). Fruit is பழம் (pazham).","tags":"","link":"tamil-fruits-and-food.html","lang":"en"},{"q":"What is mango in Tamil?","a":"Mango in Tamil is மாம்பழம் (maambazham) — from மா (mango tree) and பழம் (fruit). Banana is வாழைப்பழம் (vaazhaippazham).","tags":"","link":"tamil-fruits-and-food.html","lang":"en"},{"q":"Are the Tamil worksheets free to print?","a":"Yes. All charts and tracing worksheets on this page are free for home and classroom use. Download the PDF and print as many copies as you like.","tags":"","link":"tamil-printables.html","lang":"en"},{"q":"What paper size are the printables?","a":"They are made for A4 paper. On US Letter paper, choose “Fit to page” in the print settings.","tags":"","link":"tamil-printables.html","lang":"en"},{"q":"How should a child use the tracing worksheets?","a":"Look at the blue letter, say its sound, then trace the grey outline letters from left to right. One row a day is plenty for young children.","tags":"","link":"tamil-printables.html","lang":"en"}];
